const findDiagReportIDsByPrefix = `-- name: FindDiagReportIDsByPrefix :many
SELECT id FROM diag_reports WHERE id::text LIKE $1::text || '%' ORDER BY received_at DESC LIMIT 2
`

// The page links carry only the first 8 hex chars of a report id.
func (q *Queries) FindDiagReportIDsByPrefix(ctx context.Context, prefix string) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, findDiagReportIDsByPrefix, prefix)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

