const getLineItemsByOrderID = `-- name: GetLineItemsByOrderID :many
SELECT id, order_id, parent_id, position, sku, name, quantity, unit_price_cents, line_total_cents, notes,
       size, menu_item_id, printer_id, routing, portion, mode, coupon, coupon_no
FROM line_items WHERE order_id = $1
ORDER BY parent_id NULLS FIRST, position
`

func (q *Queries) GetLineItemsByOrderID(ctx context.Context, orderID pgtype.UUID) ([]LineItem, error) {
	rows, err := q.db.Query(ctx, getLineItemsByOrderID, orderID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LineItem
	for rows.Next() {
		var i LineItem
		if err := rows.Scan(
			&i.ID,
			&i.OrderID,
			&i.ParentID,
			&i.Position,
			&i.Sku,
			&i.Name,
			&i.Quantity,
			&i.UnitPriceCents,
			&i.LineTotalCents,
			&i.Notes,
			&i.Size,
			&i.MenuItemID,
			&i.PrinterID,
			&i.Routing,
			&i.Portion,
			&i.Mode,
			&i.Coupon,
			&i.CouponNo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

